svg.script:
/**
 * Speaker Visualizer - Beat Animation API
 *
 * Usage from your app:
 *   const viz = document.getElementById('speaker-viz');
 *   viz.triggerBeat({ sub: 1.0, mid: 0.7, hi: 0.4 });
 *   viz.setIdle(true); // resume breathing animation
 *
 * sub/mid/hi: 0.0 – 1.0 amplitude values
 */

(function() {
  const svg = document.currentScript.closest('svg') || document.getElementById('speaker-viz');

  const subWaolSpeakerWiz     = svg.querySelector('.sub-waol-speakerwiz-group');
  const neonRings   = svg.querySelectorAll('.neon-ring');
  const subRings    = svg.querySelectorAll('.sub-ring');
  const midL        = svg.querySelector('.mid-waol-speakerwiz-group-l');
  const midR        = svg.querySelector('.mid-waol-speakerwiz-group-r');
  const tweeterEls  = svg.querySelectorAll('.tweeter-l, .tweeter-r');

  let idleActive = true;
  let beatFrame  = null;

  // Baseline idle animations via CSS are already running.
  // triggerBeat temporarily overrides transforms via JS,
  // then restores to let CSS animations resume.

  function lerp(a, b, t) { return a + (b - a) * t; }

  function applyTransform(el, scale) {
    el.style.transform = `scale(${scale})`;
    el.style.transition = 'transform 0.0s';
  }

  function releaseTransform(el, duration) {
    el.style.transition = `transform ${duration}ms cubic-bezier(0.25, 0.46, 0.45, 0.94)`;
    el.style.transform = 'scale(1)';
  }

  function setNeonOpacity(rings, val) {
    rings.forEach(r => {
      r.style.opacity = val;
    });
  }

  function triggerBeat({ sub = 0, mid = 0, hi = 0 } = {}) {
    if (beatFrame) cancelAnimationFrame(beatFrame);

    const subScale   = 1 + sub  * 0.028;
    const midScale   = 1 + mid  * 0.032;
    const hiScale    = 1 + hi   * 0.05;
    const neonBright = 0.45 + sub * 0.55;
    const ringBright = 0.3 + sub * 0.7;

    // SUB
    if (subWaolSpeakerWiz) {
      subWaolSpeakerWiz.style.transition = 'none';
      subWaolSpeakerWiz.style.transform  = `scale(${subScale})`;
    }
    setNeonOpacity(neonRings, neonBright);
    setNeonOpacity(subRings,  ringBright);

    // MID
    if (midL) { midL.style.transition = 'none'; midL.style.transform = `scale(${midScale})`; }
    if (midR) { midR.style.transition = 'none'; midR.style.transform = `scale(${midScale})`; }

    // HI
    tweeterEls.forEach(t => {
      t.style.transition = 'none';
      t.style.transform  = `scale(${hiScale})`;
    });

    // Release after short attack
    const releaseMs = 80 + (1 - sub) * 60;
    beatFrame = requestAnimationFrame(() => {
      beatFrame = requestAnimationFrame(() => {
        if (subWaolSpeakerWiz) releaseTransform(subWaolSpeakerWiz, releaseMs + 40);
        if (midL)    releaseTransform(midL,    releaseMs);
        if (midR)    releaseTransform(midR,    releaseMs);
        tweeterEls.forEach(t => releaseTransform(t, releaseMs - 20));
        setNeonOpacity(neonRings, 0.7);
        setNeonOpacity(subRings,  0.5);
      });
    });
  }

  // Expose API
  svg.triggerBeat = triggerBeat;

  // Demo auto-beat for preview
  let demoActive = true;
  function demoLoop() {
    if (!demoActive) return;
    const now = Date.now();
    const bpm = 128;
    const ms  = (60 / bpm) * 1000;
    const beat = (now % ms) / ms;

    if (beat < 0.05) {
      const isKick = Math.floor(now / ms) % 2 === 0;
      triggerBeat({
        sub: isKick ? 0.9 : 0.3,
        mid: isKick ? 0.5 : 0.7,
        hi:  isKick ? 0.2 : 0.8,
      });
    }
    requestAnimationFrame(demoLoop);
  }

  // Start demo preview after brief delay
  setTimeout(() => demoLoop(), 500);

  // Stop demo when external code calls triggerBeat
  const _orig = svg.triggerBeat;
  svg.triggerBeat = function(args) {
    demoActive = false;
    _orig(args);
  };
})();
